package os.aios.core.automation;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;

/** Durable two-node-type DAG ledger. WorkManager is only a wake-up projection. */
final class DagRuntime{
 private final AutomationStore store;DagRuntime(AutomationStore s){store=s;}
 synchronized JSONObject call(String action,JSONObject p)throws Exception{
  SQLiteDatabase d=store.database();d.beginTransaction();try{JSONObject result=switch(action){case "graph.put"->put(d,p);case "graph.get"->graph(d,p.getString("id"),p.optInt("version",0));case "run.start"->start(d,p);case "run.get"->run(d,p.getString("id"));case "run.ready"->ready(d,p);case "trigger.event"->triggerEvent(d,p);case "node.claim"->claim(d,p);case "node.finish"->finish(d,p);case "run.pause","run.cancel","run.resume"->control(d,action,p);default->throw new IllegalArgumentException("Unknown DAG action: "+action);};d.setTransactionSuccessful();return result;}finally{d.endTransaction();}
 }
 private JSONObject put(SQLiteDatabase d,JSONObject p)throws Exception{
  String id=p.getString("id");JSONArray nodes=p.getJSONArray("nodes"),edges=p.optJSONArray("edges");if(nodes.length()<1||nodes.length()>256)throw new IllegalArgumentException("Graph requires 1..256 nodes");if(edges==null)edges=new JSONArray();Map<String,JSONObject> by=new LinkedHashMap<>();for(int i=0;i<nodes.length();i++){JSONObject n=nodes.getJSONObject(i);String key=n.getString("id"),kind=n.getString("kind");if(!Set.of("action","trigger").contains(kind)||by.put(key,n)!=null)throw new IllegalArgumentException("Invalid or duplicate node: "+key);if(kind.equals("trigger"))validateTrigger(n);if(n.optString("side_effect","none").equals("non_idempotent_write")&&!n.optBoolean("queryable",false))n.put("unknown_policy","wait_user");}
  Map<String,List<String>> incoming=new HashMap<>();for(int i=0;i<edges.length();i++){JSONObject e=edges.getJSONObject(i);String from=e.getString("from"),to=e.getString("to");if(!by.containsKey(from)||!by.containsKey(to)||from.equals(to))throw new IllegalArgumentException("Invalid dependency");incoming.computeIfAbsent(to,k->new ArrayList<>()).add(from);}Set<String> visiting=new HashSet<>(),done=new HashSet<>();for(String n:by.keySet())visit(n,incoming,visiting,done);
  int version=scalar(d,"SELECT COALESCE(MAX(version),0)+1 FROM graphs WHERE id=?",id);JSONObject def=new JSONObject(p.toString()).put("version",version).put("join","and");d.execSQL("INSERT INTO graphs VALUES(?,?,?,?)",new Object[]{id,version,def.toString(),System.currentTimeMillis()});return def;
 }
 private void visit(String n,Map<String,List<String>> incoming,Set<String> visiting,Set<String> done){if(done.contains(n))return;if(!visiting.add(n))throw new IllegalArgumentException("Graph contains a cycle");for(String p:incoming.getOrDefault(n,List.of()))visit(p,incoming,visiting,done);visiting.remove(n);done.add(n);}
 private void validateTrigger(JSONObject node)throws Exception{JSONObject trigger=node.optJSONObject("trigger");if(trigger==null)throw new IllegalArgumentException("Trigger node requires trigger spec");String type=trigger.getString("type");if(!Set.of("time","topic","device").contains(type))throw new IllegalArgumentException("Unsupported trigger type: "+type);if(type.equals("time")&&!trigger.has("not_before")&&!node.has("not_before"))throw new IllegalArgumentException("Time trigger requires not_before");if((type.equals("topic")||type.equals("device"))&&trigger.optString("topic").isBlank())throw new IllegalArgumentException("Event trigger requires topic");}
 private JSONObject start(SQLiteDatabase d,JSONObject p)throws Exception{
  JSONObject g=graph(d,p.getString("graph_id"),p.optInt("graph_version",0));new PolicyLedger(store).require(p.getString("authorization_id"),"scheduler.execute","",1);JSONObject authorization=new PolicyLedger(store).get(p.getString("authorization_id"));if(authorization.has("graph_id")&&(!authorization.getString("graph_id").equals(g.getString("id"))||authorization.optInt("graph_version")!=g.getInt("version")))throw new SecurityException("Authorization bound to another graph version");String occurrence=p.getString("occurrence");JSONObject existing=one(d,"SELECT * FROM graph_runs WHERE graph_id=? AND occurrence=?",g.getString("id"),occurrence);if(existing!=null)return existing.put("existing",true);String id=UUID.randomUUID().toString();long now=System.currentTimeMillis();d.execSQL("INSERT INTO graph_runs VALUES(?,?,?,?,'running',?,?,1,?,?)",new Object[]{id,g.getString("id"),g.getInt("version"),occurrence,p.optString("task_id"),p.getString("authorization_id"),now,now});JSONArray nodes=g.getJSONArray("nodes");for(int i=0;i<nodes.length();i++){JSONObject n=nodes.getJSONObject(i);String state=n.getString("kind").equals("trigger")?"waiting_trigger":"waiting_dependency";JSONObject trigger=n.optJSONObject("trigger");long notBefore=trigger!=null&&trigger.optString("type").equals("time")?trigger.optLong("not_before",n.optLong("not_before",0)):n.optLong("not_before",0);d.execSQL("INSERT INTO graph_nodes(run_id,node_id,kind,state,not_before,request_id,param_fingerprint,side_effect,updated_at,trigger_spec,resource) VALUES(?,?,?,?,?,?,?,?,?,?,?)",new Object[]{id,n.getString("id"),n.getString("kind"),state,notBefore,n.optString("request_id",os.aios.runtime.CoreContracts.stableId("node",id,n.getString("id"))),n.optString("param_fingerprint",""),n.optString("side_effect","none"),now,trigger==null?"{}":trigger.toString(),n.optString("resource","")});}JSONArray edges=g.optJSONArray("edges");if(edges!=null)for(int i=0;i<edges.length();i++){JSONObject e=edges.getJSONObject(i);d.execSQL("INSERT INTO graph_edges VALUES(?,?,?,?)",new Object[]{id,e.getString("to"),e.getString("from"),e.optString("on_state","succeeded")});}refresh(d,id,now);return run(d,id);
 }
 private JSONObject triggerEvent(SQLiteDatabase d,JSONObject event)throws Exception{String topic=event.getString("topic");JSONObject data=event.optJSONObject("data");if(data==null)data=new JSONObject();JSONArray waiting=rows(d,"SELECT * FROM graph_nodes WHERE kind='trigger' AND state='waiting_trigger'");JSONArray matched=new JSONArray();for(int i=0;i<waiting.length();i++){JSONObject n=waiting.getJSONObject(i),spec=new JSONObject(n.getString("trigger_spec"));String type=spec.optString("type");if(!(type.equals("topic")||type.equals("device"))||!topic.equals(spec.optString("topic"))||!matches(data,spec.optJSONObject("equals")))continue;long now=System.currentTimeMillis();d.execSQL("UPDATE graph_nodes SET state='succeeded',result=?,updated_at=? WHERE run_id=? AND node_id=?",new Object[]{event.toString(),now,n.getString("run_id"),n.getString("node_id")});refresh(d,n.getString("run_id"),now);matched.put(new JSONObject().put("run_id",n.getString("run_id")).put("node_id",n.getString("node_id")));}return new JSONObject().put("matched",matched);}
 private boolean matches(JSONObject data,JSONObject expected)throws Exception{if(expected==null)return true;Iterator<String> keys=expected.keys();while(keys.hasNext()){String key=keys.next();if(!data.has(key)||!String.valueOf(data.opt(key)).equals(String.valueOf(expected.opt(key))))return false;}return true;}
 private JSONObject ready(SQLiteDatabase d,JSONObject p)throws Exception{refresh(d,p.getString("id"),p.optLong("now",System.currentTimeMillis()));return new JSONObject().put("items",rows(d,"SELECT * FROM graph_nodes WHERE run_id=? AND (state='ready' OR (state='running' AND lease_until<="+System.currentTimeMillis()+")) ORDER BY node_id",p.getString("id")));}
 private JSONObject claim(SQLiteDatabase d,JSONObject p)throws Exception{String run=p.getString("run_id"),node=p.getString("node_id"),owner=p.getString("owner");long now=System.currentTimeMillis(),ttl=Math.max(5000,Math.min(300000,p.optLong("lease_ms",60000)));JSONObject runState=required(d,"graph_runs","id=?",run);if(!runState.getString("state").equals("running"))throw new IllegalStateException("Run is not executable");new PolicyLedger(store).require(runState.getString("authorization_id"),"scheduler.execute","",1);JSONObject old=required(d,"graph_nodes","run_id=? AND node_id=?",run,node);if(!old.getString("state").equals("ready")&&!(old.getString("state").equals("running")&&old.getLong("lease_until")<=now))throw new IllegalStateException("Node not claimable");String resource=old.getString("resource");if(!resource.isEmpty()){JSONObject r=required(d,"graph_runs","id=?",run);try{new PolicyLedger(store).acquire(r.getString("authorization_id"),owner,resource,ttl);}catch(IllegalStateException busy){d.execSQL("UPDATE graph_nodes SET state='waiting_resource',updated_at=? WHERE run_id=? AND node_id=?",new Object[]{now,run,node});return required(d,"graph_nodes","run_id=? AND node_id=?",run,node);}}int generation=old.getInt("generation")+1,attempt=old.getInt("attempt")+1;d.execSQL("UPDATE graph_nodes SET state='running',generation=?,attempt=?,lease_owner=?,lease_until=?,updated_at=? WHERE run_id=? AND node_id=?",new Object[]{generation,attempt,owner,now+ttl,now,run,node});String id=UUID.randomUUID().toString();d.execSQL("INSERT INTO graph_attempts VALUES(?,?,?,?,?,'submitting',?,'{}',?,0)",new Object[]{id,run,node,attempt,generation,new JSONObject().put("request_id",old.getString("request_id")).put("param_fingerprint",old.getString("param_fingerprint")).toString(),now});return required(d,"graph_nodes","run_id=? AND node_id=?",run,node).put("attempt_id",id);}
 private JSONObject finish(SQLiteDatabase d,JSONObject p)throws Exception{String run=p.getString("run_id"),node=p.getString("node_id"),state=p.getString("state");JSONObject old=required(d,"graph_nodes","run_id=? AND node_id=?",run,node);if(!required(d,"graph_runs","id=?",run).getString("state").equals("running")||old.getLong("lease_until")<=System.currentTimeMillis()||!old.getString("state").equals("running"))throw new IllegalStateException("Run stopped or lease expired");if(old.getInt("generation")!=p.getInt("generation")||!old.getString("lease_owner").equals(p.getString("owner")))throw new IllegalStateException("Stale node lease");new PolicyLedger(store).require(required(d,"graph_runs","id=?",run).getString("authorization_id"),"scheduler.execute",old.getString("resource"),1);os.aios.runtime.CoreContracts.requireTransition(old.getString("state"),state);d.execSQL("UPDATE graph_nodes SET state=?,result=?,error=?,lease_owner='',lease_until=0,updated_at=? WHERE run_id=? AND node_id=?",new Object[]{state,p.optJSONObject("result")==null?"{}":p.getJSONObject("result").toString(),p.optString("error"),System.currentTimeMillis(),run,node});d.execSQL("UPDATE graph_attempts SET state=?,receipt=?,finished_at=? WHERE run_id=? AND node_id=? AND generation=?",new Object[]{state,p.optJSONObject("result")==null?"{}":p.getJSONObject("result").toString(),System.currentTimeMillis(),run,node,p.getInt("generation")});new PolicyLedger(store).release(p.getString("owner"));refresh(d,run,System.currentTimeMillis());return run(d,run);}
 private JSONObject control(SQLiteDatabase d,String action,JSONObject p)throws Exception{
  String id=p.getString("id");JSONObject r=required(d,"graph_runs","id=?",id);String next=action.endsWith("pause")?"paused":action.endsWith("cancel")?"cancelled":"running";os.aios.runtime.CoreContracts.requireTransition(r.getString("state"),next);long now=System.currentTimeMillis();
  d.execSQL("UPDATE graph_runs SET state=?,generation=generation+1,updated_at=? WHERE id=?",new Object[]{next,now,id});
  if(!next.equals("running")){
   JSONArray leased=rows(d,"SELECT lease_owner FROM graph_nodes WHERE run_id=? AND lease_owner<>''",id);for(int i=0;i<leased.length();i++)new PolicyLedger(store).release(leased.getJSONObject(i).getString("lease_owner"));
   d.execSQL("UPDATE graph_attempts SET state=?,finished_at=? WHERE run_id=? AND finished_at=0",new Object[]{next.equals("cancelled")?"cancelled":"interrupted",now,id});
   d.execSQL("UPDATE graph_nodes SET state=CASE WHEN ?='cancelled' THEN 'cancelled' WHEN state IN ('running','submitting') AND side_effect='non_idempotent_write' THEN 'outcome_unknown' WHEN state IN ('running','submitting') THEN 'waiting_resource' ELSE state END,generation=generation+1,lease_owner='',lease_until=0,updated_at=? WHERE run_id=? AND state NOT IN ('succeeded','failed','cancelled')",new Object[]{next,now,id});
  }else refresh(d,id,now);
  return run(d,id);
 }
 private void refresh(SQLiteDatabase d,String run,long now)throws Exception{JSONObject r=required(d,"graph_runs","id=?",run);if(!r.getString("state").equals("running"))return;JSONArray nodes=rows(d,"SELECT * FROM graph_nodes WHERE run_id=?",run);for(int i=0;i<nodes.length();i++){JSONObject n=nodes.getJSONObject(i);String state=n.getString("state");if(state.equals("waiting_resource"))d.execSQL("UPDATE graph_nodes SET state='ready',updated_at=? WHERE run_id=? AND node_id=?",new Object[]{now,run,n.getString("node_id")});else if(n.getString("kind").equals("trigger")&&state.equals("waiting_trigger")){JSONObject spec=new JSONObject(n.getString("trigger_spec"));if(spec.optString("type").equals("time")&&n.getLong("not_before")<=now)d.execSQL("UPDATE graph_nodes SET state='succeeded',updated_at=? WHERE run_id=? AND node_id=?",new Object[]{now,run,n.getString("node_id")});}else if(state.equals("waiting_dependency")){int unmet=scalar(d,"SELECT count(*) FROM graph_edges e JOIN graph_nodes p ON p.run_id=e.run_id AND p.node_id=e.requires_node WHERE e.run_id=? AND e.node_id='"+n.getString("node_id").replace("'","''")+"' AND p.state<>e.on_state",run);if(unmet==0)d.execSQL("UPDATE graph_nodes SET state='ready',updated_at=? WHERE run_id=? AND node_id=?",new Object[]{now,run,n.getString("node_id")});}}
  int open=scalar(d,"SELECT count(*) FROM graph_nodes WHERE run_id=? AND state NOT IN ('succeeded','cancelled')",run),failed=scalar(d,"SELECT count(*) FROM graph_nodes WHERE run_id=? AND state IN ('failed','outcome_unknown','waiting_user')",run);if(open==0)d.execSQL("UPDATE graph_runs SET state='succeeded',updated_at=? WHERE id=?",new Object[]{now,run});else if(failed>0)d.execSQL("UPDATE graph_runs SET state=CASE WHEN EXISTS(SELECT 1 FROM graph_nodes WHERE run_id=? AND state IN ('outcome_unknown','waiting_user')) THEN 'waiting_user' ELSE 'failed' END,updated_at=? WHERE id=?",new Object[]{run,now,run});}
 private JSONObject graph(SQLiteDatabase d,String id,int version)throws Exception{JSONObject row=version==0?required(d,"graphs","id=? ORDER BY version DESC LIMIT 1",id):required(d,"graphs","id=? AND version=?",id,Integer.toString(version));return new JSONObject(row.getString("definition"));}
 private JSONObject run(SQLiteDatabase d,String id)throws Exception{return required(d,"graph_runs","id=?",id).put("nodes",rows(d,"SELECT * FROM graph_nodes WHERE run_id=? ORDER BY node_id",id));}
 private JSONObject required(SQLiteDatabase d,String table,String where,String...args)throws Exception{JSONObject o=one(d,"SELECT * FROM "+table+" WHERE "+where,args);if(o==null)throw new IllegalArgumentException("Record not found");return o;}
 private JSONObject one(SQLiteDatabase d,String sql,String...args)throws Exception{try(Cursor c=d.rawQuery(sql,args)){return c.moveToFirst()?row(c):null;}}
 private JSONArray rows(SQLiteDatabase d,String sql,String...args)throws Exception{JSONArray a=new JSONArray();try(Cursor c=d.rawQuery(sql,args)){while(c.moveToNext())a.put(row(c));}return a;}
 private JSONObject row(Cursor c)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<c.getColumnCount();i++)o.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));return o;}
 private int scalar(SQLiteDatabase d,String sql,String...args){try(Cursor c=d.rawQuery(sql,args)){c.moveToFirst();return c.getInt(0);}}
}
